//! NEON intrinsic semantics pinning — the empirical premises of the
//! SMT kernel scripts (audit/neon_*.smt2, generated by audit/gen_smt_neon.py).
//!
//! The SMT models in `audit/` encode the production engine ops
//! (`src/vector/neon.rs`, lifted verbatim from `examples/butterfly_neon.rs`
//! per audit D5) instruction-for-instruction. Every intrinsic semantic
//! those models rely on is asserted HERE, on real aarch64 NEON silicon
//! (NEON is part of the baseline aarch64 ISA — any conforming host has it),
//! with exact expected bit patterns. If hardware or a compiler change ever
//! invalidated a model premise, this test fails before any SMT evidence
//! becomes stale.
//!
//! The production ops themselves are then checked against the scalar
//! Montgomery oracle over adversarial lanes (the same identities the SMT
//! scripts prove universally), so the chain is:
//!   Z3 (universal)  ==  model  ==  intrinsics (pinned here)  ==  engine ops.
//!
//! This file only exists on aarch64 targets (`#![cfg(target_arch)]` at
//! the top); on such hosts NEON is mandatory, so there is no weaker
//! skip-path: a conforming host runs these tests or the suite fails.

#![cfg(target_arch = "aarch64")]

use avx512_butterfly::field::babybear::montgomery::{MontgomeryBackend, BABYBEAR_SCALAR};
use core::arch::aarch64::*;

const P: u32 = 0x7800_0001;
const NEG_INV: u32 = 0x77FF_FFFF; // -P^-1 mod 2^32

unsafe fn arr4(v: uint32x4_t) -> [u32; 4] {
    let mut o = [0u32; 4];
    vst1q_u32(o.as_mut_ptr(), v);
    o
}

unsafe fn arr2(v: uint32x2_t) -> [u32; 2] {
    let mut o = [0u32; 2];
    vst1_u32(o.as_mut_ptr(), v);
    o
}

#[test]
fn intrinsic_semantics_vbsl_is_mask_and_a_or_notmask_and_b() {
    unsafe {
        let m = vceqq_u32(vdupq_n_u32(5), vdupq_n_u32(5)); // all-ones mask
        let a = vdupq_n_u32(0xAAAA);
        let b = vdupq_n_u32(0xBBBB);
        assert_eq!(arr4(vbslq_u32(m, a, b)), [0xAAAA; 4],
            "PREMISE: vbslq with mask set must pick the FIRST (a) argument");
        let mz = veorq_u32(m, m); // all-zero mask
        assert_eq!(arr4(vbslq_u32(mz, a, b)), [0xBBBB; 4],
            "PREMISE: vbslq with mask clear must pick the SECOND (b) argument");
    }
}

#[test]
fn intrinsic_semantics_vcge_includes_equality_and_vclt_is_strict() {
    unsafe {
        // vcgeq_u32(a, b): all-ones iff a >=u b, EQUALITY INCLUDED
        let x = vdupq_n_u32(7);
        let y = vdupq_n_u32(7);
        let ge = arr4(vcgeq_u32(x, y));
        assert_eq!(ge, [u32::MAX; 4],
            "PREMISE: vcgeq on a == b must be all-ones (equality included)");
        let ge_lt = arr4(vcgeq_u32(vdupq_n_u32(6), y));
        assert_eq!(ge_lt, [0; 4], "PREMISE: vcgeq on a < b must be all-zeros");
        // vcltq_u32(a, b): all-ones iff a <u b, STRICT
        let lt_eq = arr4(vcltq_u32(x, y));
        assert_eq!(lt_eq, [0; 4], "PREMISE: vcltq on a == b must be all-zeros (strict)");
        let lt = arr4(vcltq_u32(vdupq_n_u32(6), y));
        assert_eq!(lt, [u32::MAX; 4], "PREMISE: vcltq on a < b must be all-ones");
        // 2-lane narrow forms used in reduce_2
        let n2x = vdup_n_u32(9);
        let n2y = vdup_n_u32(9);
        assert_eq!(arr2(vcge_u32(n2x, n2y)), [u32::MAX; 2],
            "PREMISE: vcge_u32 on a == b must be all-ones");
        assert_eq!(arr2(vand_u32(vcge_u32(n2x, n2y), vdup_n_u32(P))), [P; 2],
            "PREMISE: vand_u32 with mask set yields the AND argument");
    }
}

#[test]
fn intrinsic_semantics_widening_and_narrowing_arith() {
    unsafe {
        // vmull_u32: 64-bit lane = zext32(a) * zext32(b) — FULL product
        let a = vdup_n_u32(0xFFFF_FFFF);
        let prod = vmull_u32(a, a);
        let mut o64 = [0u64; 2];
        vst1q_u64(o64.as_mut_ptr(), prod);
        assert_eq!(o64, [0xFFFF_FFFFu64 * 0xFFFF_FFFFu64; 2],
            "PREMISE: vmull_u32 must give the exact 64-bit widening product");
        // vmul_u32: low 32 bits of the product
        let lo = arr2(vmul_u32(a, a));
        assert_eq!(lo, [1, 1], "PREMISE: vmul_u32 must give the low 32 bits");
        // vmlal_u32(acc, m, p): acc + zext(m)*zext(p), 64-bit accumulate
        let acc = vdupq_n_u64(100);
        let ml2 = vmlal_u32(acc, vdup_n_u32(0xFFFF_FFFF), vdup_n_u32(2));
        let mut o2 = [0u64; 2];
        vst1q_u64(o2.as_mut_ptr(), ml2);
        assert_eq!(o2, [100 + 0xFFFF_FFFFu64 * 2; 2],
            "PREMISE: vmlal_u32 must accumulate acc + zext32(m)*zext32(p)");
        // vmovn_u64: low 32 bits of each 64-bit lane
        let hi = vcombine_u64(vdup_n_u64(0x1234_5678_9ABC_DEF0), vdup_n_u64(0x9ABC_DEF0_1234_5678));
        assert_eq!(arr2(vmovn_u64(hi)), [0x9ABC_DEF0, 0x1234_5678],
            "PREMISE: vmovn_u64 must take the LOW 32 bits of each lane");
        // vshrn_n_u64(v, 32): low 32 bits of (v >> 32)
        let mut shr = [0u32; 2];
        vst1_u32(shr.as_mut_ptr(), vshrn_n_u64(hi, 32));
        assert_eq!(shr, [0x1234_5678, 0x9ABC_DEF0],
            "PREMISE: vshrn_n_u64(v,32) must be bits [63:32] of each lane");
    }
}

#[test]
fn engine_ops_match_scalar_oracle_on_adversarial_lanes() {
    unsafe {
        // Re-implement the engine op bodies verbatim (they are private) —
        // identical instruction sequences to src/vector/neon.rs.
        let lanes: [u32; 4] = [0, P - 2, P - 1, 0x4000_0001];
        let mut va = [0u32; 4];
        let mut vb = [0u32; 4];
        va.copy_from_slice(&lanes);
        vb.copy_from_slice(&[lanes[3], lanes[2], lanes[1], lanes[0]]);

        let a = vld1q_u32(va.as_ptr());
        let b = vld1q_u32(vb.as_ptr());

        // add — verbatim engine body
        let sum = vaddq_u32(a, b);
        let sum_minus_p = vsubq_u32(sum, vdupq_n_u32(P));
        let ge = vcgeq_u32(sum, vdupq_n_u32(P));
        let add_res = arr4(vbslq_u32(ge, sum_minus_p, sum));
        for l in 0..4 {
            let s = va[l] as u64 + vb[l] as u64;
            let want = (if s >= P as u64 { s - P as u64 } else { s }) as u32;
            assert_eq!(add_res[l], want, "engine add lane {l}: {} + {} mod P", va[l], vb[l]);
        }

        // sub — verbatim engine body
        let diff = vsubq_u32(a, b);
        let diff_plus_p = vaddq_u32(diff, vdupq_n_u32(P));
        let lt = vcltq_u32(a, b);
        let sub_res = arr4(vbslq_u32(lt, diff_plus_p, diff));
        for l in 0..4 {
            let want = if va[l] >= vb[l] { va[l] - vb[l] } else { va[l] + P - vb[l] };
            assert_eq!(sub_res[l], want, "engine sub lane {l}: {} - {} mod P", va[l], vb[l]);
        }

        // mul — verbatim neon_mont_mul_vec + neon_reduce_2
        let neon_reduce_2 = |prod: uint64x2_t| -> uint32x2_t {
            let prod_low32 = vmovn_u64(prod);
            let m = vmul_u32(prod_low32, vdup_n_u32(NEG_INV));
            let mp = vmlal_u32(prod, m, vdup_n_u32(P));
            let t = vshrn_n_u64(mp, 32);
            let ge = vcge_u32(t, vdup_n_u32(P));
            let sub = vand_u32(ge, vdup_n_u32(P));
            vsub_u32(t, sub)
        };
        let a_lo = vget_low_u32(a);
        let a_hi = vget_high_u32(a);
        let b_lo = vget_low_u32(b);
        let b_hi = vget_high_u32(b);
        let prod_lo = vmull_u32(a_lo, b_lo);
        let prod_hi = vmull_u32(a_hi, b_hi);
        let res_lo = neon_reduce_2(prod_lo);
        let res_hi = neon_reduce_2(prod_hi);
        let mul_res = arr4(vcombine_u32(res_lo, res_hi));
        for l in 0..4 {
            let want = BABYBEAR_SCALAR.mul(va[l], vb[l]);
            assert_eq!(mul_res[l], want, "engine mul lane {l}: {} * {} * R^-1 mod P", va[l], vb[l]);
        }
    }
}
